INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''raglan sleeve'' construction, and how does it differ from a standard ''set-in sleeve''?', '["A raglan sleeve extends in one piece diagonally up to the neckline (no separate shoulder seam), while a set-in sleeve is attached at a rounded armhole seam with a distinct shoulder line","Raglan and set-in sleeves are structurally identical with no visible difference","A raglan sleeve has no sleeve seam at all, unlike a set-in sleeve","Set-in sleeves are used only for sleeveless garments"]'::jsonb, 'A raglan sleeve extends in one piece diagonally up to the neckline (no separate shoulder seam), while a set-in sleeve is attached at a rounded armhole seam with a distinct shoulder line', 'Raglan sleeves have a diagonal seam running from the underarm to the neckline, with the sleeve and shoulder cut as one continuous piece — unlike set-in sleeves, which attach at a curved armhole seam with a distinct, separate shoulder line, giving each construction a different look and range of arm motion.', 1, '{"raglan-sleeve"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is a ''princess seam'' in garment construction?', '["A curved vertical seam (running from shoulder or armhole to hem) used to shape a garment closely to the body without darts","A seam used only on children''s garments","A horizontal seam at the waistline of a dress","A decorative seam with no shaping function"]'::jsonb, 'A curved vertical seam (running from shoulder or armhole to hem) used to shape a garment closely to the body without darts', 'Princess seams are curved vertical seams that shape a garment to the body''s contours (bust, waist, hip) as an alternative to using separate darts — commonly used in fitted dresses and jackets for a smooth, tailored silhouette.', 2, '{"princess-seam"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''dart'' in garment pattern making?', '["A folded and stitched wedge of fabric used to shape flat fabric to fit a body''s three-dimensional curves","A type of fastener used instead of buttons","A decorative stitch pattern with no shaping function","A tool used to measure fabric width"]'::jsonb, 'A folded and stitched wedge of fabric used to shape flat fabric to fit a body''s three-dimensional curves', 'A dart is a tapered fold of fabric, stitched to a point, that removes excess flat fabric to create three-dimensional shaping — commonly used at the bust, waist, or shoulder to help a flat pattern fit the body''s curves.', 1, '{"dart"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''gusset'' in garment construction (e.g., underarm gusset)?', '["A small, separate piece of fabric inserted into a garment to add ease of movement or reinforce a stress point","The main body panel of a garment","A type of collar construction","A decorative trim applied to a hemline"]'::jsonb, 'A small, separate piece of fabric inserted into a garment to add ease of movement or reinforce a stress point', 'A gusset is a small inserted fabric piece (often diamond or triangular shaped) added at a high-movement or high-stress area, like the underarm, to provide extra ease of movement and/or reduce strain on the surrounding seams.', 1, '{"gusset"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''yoke'' in garment construction (e.g., a shirt yoke)?', '["A separate fabric panel, typically across the shoulders/upper back, that provides shaping and sometimes a grain-line or design change from the rest of the garment","A type of fastening closure at the garment''s front","A decorative trim added only to sleeve cuffs","A term describing the garment''s overall size category"]'::jsonb, 'A separate fabric panel, typically across the shoulders/upper back, that provides shaping and sometimes a grain-line or design change from the rest of the garment', 'A yoke is a distinct fabric panel — commonly across the shoulders and upper back of a shirt — that can provide better fit/shaping, allow a different grain direction for design effect, or add reinforcement where the garment experiences more stress.', 1, '{"yoke"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is ''French seam'' construction, and what advantage does it offer over a plain raw-edge seam?', '["A seam sewn twice (first with wrong sides together, then trimmed and re-sewn with right sides together) that fully encloses the raw edges inside, preventing fraying with a clean finish on both sides","A seam that uses no stitching at all, relying only on fabric adhesive","A seam that is always visible and decorative, never enclosed","A seam used exclusively for attaching zippers"]'::jsonb, 'A seam sewn twice (first with wrong sides together, then trimmed and re-sewn with right sides together) that fully encloses the raw edges inside, preventing fraying with a clean finish on both sides', 'A French seam is constructed by first stitching wrong-sides-together, trimming close to the stitch line, then folding and stitching again right-sides-together — this fully encloses the raw fabric edges inside the seam, giving a clean, fray-resistant finish visible from both the inside and outside.', 2, '{"french-seam"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why might French seam construction be preferred for lightweight or sheer fabrics specifically?', '["Since the fabric is thin/transparent, an unfinished or overlocked raw edge would be visible and look unfinished, while a French seam''s fully enclosed edge looks clean from both sides","French seams are only physically possible on heavy, thick fabrics, never lightweight ones","Lightweight fabric has no relationship to which seam finishing method is chosen","French seams are always faster to sew than any other seam type, unrelated to fabric weight"]'::jsonb, 'Since the fabric is thin/transparent, an unfinished or overlocked raw edge would be visible and look unfinished, while a French seam''s fully enclosed edge looks clean from both sides', 'On sheer or lightweight fabrics, an exposed or overlocked raw seam edge is often visible through the fabric and looks unfinished; French seam''s fully enclosed construction hides all raw edges, giving a clean appearance from both the outside and inside — especially valued for delicate, see-through fabrics.', 2, '{"french-seam-application"}'::text[]);
